import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.BUS5y9ZA.js";const p=JSON.parse('{"title":"로그인 세션 관리","description":"","frontmatter":{},"headers":[],"relativePath":"manage_session.md","filePath":"manage_session.md"}'),l={name:"manage_session.md"};function d(s,e,r,c,n,u){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="로그인-세션-관리" tabindex="-1">로그인 세션 관리 <a class="header-anchor" href="#로그인-세션-관리" aria-label="Permalink to &quot;로그인 세션 관리&quot;">​</a></h1><h2 id="_1-목적" tabindex="-1">1. 목적 <a class="header-anchor" href="#_1-목적" aria-label="Permalink to &quot;1. 목적&quot;">​</a></h2><p>근무자와 관리자의 로그인 상태는 사용자가 명시적으로 로그아웃할 때까지 유지한다. 다만 로그인 상태와 업무 권한은 분리하여, 퇴직·계정 삭제·관리자 권한 회수 시에는 저장된 세션이 남아 있더라도 서버가 접근을 거부한다.</p><h2 id="_2-근무자-세션" tabindex="-1">2. 근무자 세션 <a class="header-anchor" href="#_2-근무자-세션" aria-label="Permalink to &quot;2. 근무자 세션&quot;">​</a></h2><ul><li>근무자 세션은 브라우저 <code>localStorage</code>의 <code>ollbareun.guard.session</code>에 저장한다.</li><li>기존의 마지막 활동 후 24시간 만료 정책은 사용하지 않는다.</li><li>브라우저나 탭을 닫았다가 다시 열어도 세션을 복원한다.</li><li>과거 <code>sessionStorage</code>에 저장된 세션은 <code>localStorage</code>로 이전하여 호환한다.</li><li>메인 화면 진입 시 서버에서 직원 정보를 다시 조회하고 최신 배정·근태 정보를 반영한다.</li><li>직원이 퇴직 또는 삭제된 경우 저장된 세션을 제거하고 근무자 로그인 화면으로 이동한다.</li><li>출퇴근, 교육 이수, 현장점검, 특이사항 보고, Push 등록 등 주요 변경 API도 처리 전에 재직 상태를 확인하며, 권한이 없으면 HTTP 403으로 거부한다.</li><li>로그아웃 시 근무자 로컬 세션, 레거시 세션, Push 등록 정보 및 Passkey용 Supabase 세션을 정리한다.</li></ul><h2 id="_3-관리자-세션" tabindex="-1">3. 관리자 세션 <a class="header-anchor" href="#_3-관리자-세션" aria-label="Permalink to &quot;3. 관리자 세션&quot;">​</a></h2><ul><li>관리자 인증은 Supabase Auth의 access token과 refresh token을 사용한다.</li><li>브라우저 종료 여부를 판단하던 <code>sessionStorage</code> 표식과 강제 로그아웃 게이트는 사용하지 않는다.</li><li>브라우저를 다시 실행해도 Supabase refresh token이 유효하면 로그인 상태를 복원한다.</li><li>JWT 만료 시간을 무제한으로 늘리지 않고 짧은 access token을 refresh token으로 갱신한다.</li><li>관리자 화면과 관리자 API는 요청마다 Supabase 사용자와 <code>admin_users</code> 등록 상태를 확인한다.</li><li>관리자가 삭제되거나 권한이 회수되면 기존 브라우저 세션이 남아 있어도 접근을 거부한다.</li><li>관리자 헤더의 로그아웃 버튼은 Supabase <code>signOut()</code>을 실행한 후 관리자 로그인 화면으로 이동한다.</li></ul><h2 id="_4-권한-회수-원칙" tabindex="-1">4. 권한 회수 원칙 <a class="header-anchor" href="#_4-권한-회수-원칙" aria-label="Permalink to &quot;4. 권한 회수 원칙&quot;">​</a></h2><p>무제한 로그인은 무제한 권한을 의미하지 않는다.</p><table tabindex="0"><thead><tr><th>상태</th><th>로그인 데이터</th><th>서버 접근</th></tr></thead><tbody><tr><td>정상 근무자·관리자</td><td>명시적 로그아웃 전까지 유지</td><td>허용</td></tr><tr><td>퇴직·삭제 근무자</td><td>다음 서버 검증 시 제거</td><td>거부</td></tr><tr><td>삭제·권한 회수 관리자</td><td>Supabase 세션이 남을 수 있음</td><td><code>admin_users</code> 검증으로 거부</td></tr><tr><td>사용자가 로그아웃</td><td>브라우저와 인증 세션 정리</td><td>거부</td></tr><tr><td>브라우저 사이트 데이터 삭제</td><td>세션 소실</td><td>재로그인 필요</td></tr></tbody></table><p>재입사 또는 관리자 권한 재부여 시에는 보안을 위해 다시 로그인한다.</p><h2 id="_5-supabase-운영-설정" tabindex="-1">5. Supabase 운영 설정 <a class="header-anchor" href="#_5-supabase-운영-설정" aria-label="Permalink to &quot;5. Supabase 운영 설정&quot;">​</a></h2><p>Supabase Dashboard의 <strong>Authentication → Sessions</strong>에서 다음 항목을 확인한다.</p><ul><li><code>Time-box user sessions</code>: 비활성화</li><li><code>Inactivity timeout</code>: 비활성화</li><li><code>Single session per user</code>: 여러 기기에서 로그인 상태를 유지해야 하면 비활성화</li><li>JWT 만료 시간: 권장 기본값인 약 1시간 유지</li></ul><p>비밀번호 변경, 보안상 민감한 작업, 세션 폐기 또는 Supabase 정책에 의해 refresh token이 무효화된 경우에는 다시 로그인해야 한다.</p><h2 id="_6-검증-기준" tabindex="-1">6. 검증 기준 <a class="header-anchor" href="#_6-검증-기준" aria-label="Permalink to &quot;6. 검증 기준&quot;">​</a></h2><ul><li>근무자는 마지막 활동 후 24시간 이상 지나도 로그인 상태가 복원된다.</li><li>관리자도 브라우저 종료 후 다시 접속했을 때 로그인 상태가 복원된다.</li><li>퇴직·삭제된 근무자의 화면 진입과 주요 변경 API가 차단된다.</li><li>삭제되거나 권한이 회수된 관리자의 보호 화면과 API 접근이 차단된다.</li><li>근무자와 관리자의 명시적 로그아웃 이후 보호 화면에 다시 접근할 수 없다.</li></ul><h2 id="_7-빌드" tabindex="-1">7. 빌드 <a class="header-anchor" href="#_7-빌드" aria-label="Permalink to &quot;7. 빌드&quot;">​</a></h2><p>프로젝트의 <code>npm run build</code>는 다음 순서로 실행된다.</p><ol><li><code>npm run docs:build</code></li><li><code>vitepress build docs --outDir public/docs/documents</code></li><li><code>next build --webpack</code></li></ol><p>따라서 전체 빌드를 실행하면 이 문서를 포함한 VitePress 결과물이 <code>public/docs/documents</code>에 먼저 생성된 후 Next.js production build가 실행된다.</p>',21)])])}const b=a(l,[["render",d]]);export{p as __pageData,b as default};
